async function inspectFrame(name){let s=await app.getAXState({disableDiffing:true});let re=new RegExp("^\s*(\d+) row(?: \(selected\))? "+name.replace(/[.*+?^${}()|[\]\]/g,'\$&')+"(?:\s|$)","m");let m=s.match(re);if(!m)return [name,"row not found"];await app.click(Number(m[1]));await new Promise(r=>setTimeout(r,180));let t=await app.getAXState({disableDiffing:true});let x=(t.match(/X-position, Value: ([^
]+)/)||[])[1];let y=(t.match(/Y-position, Value: ([^
]+)/)||[])[1];let w=(t.match(/Description: Width, Value: ([^
]+)/)||[])[1];let h=(t.match(/Description: Height, Value: ([^
]+)/)||[])[1];return [name,x,y,w,h];}
let results=[];for(let n of ["Flow A Start","Flow A End","Flow B Start","Flow B End","Shared Hub"]){results.push(await inspectFrame(n));}nodeRepl.write(results);

